import { test, expect } from '@playwright/test';

test.describe('Responsive Image Scaling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display images scaled down on mobile view', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 }); // Mobile viewport size
    const image = page.getByRole('img', { name: /example image/i }); // Replace with actual image alt text
    const boundingBox = await image.boundingBox();

    expect(boundingBox).not.toBeNull();
    expect(boundingBox.width).toBeLessThanOrEqual(375); // Ensure image width fits the screen
  });

  test('should maintain aspect ratio of images on mobile view', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 }); // Mobile viewport size
    const image = page.getByRole('img', { name: /example image/i }); // Replace with actual image alt text
    const originalWidth = 800; // Replace with the original image width
    const originalHeight = 600; // Replace with the original image height
    const boundingBox = await image.boundingBox();

    expect(boundingBox).not.toBeNull();
    const scaledHeight = (boundingBox.width / originalWidth) * originalHeight;
    expect(boundingBox.height).toBeCloseTo(scaledHeight, { tolerance: 1 }); // Allow for minor discrepancies
  });
});
